def transform(grid):
 out=[row[:] for row in grid]
 for color in set(v for row in grid for v in row if v not in (9,)):
  pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color]
  if len(pts)<2: continue
  # use aligned diagonal repeated cells
  for i,(r,c) in enumerate(pts):
   for rr,cc in pts[i+1:]:
    if abs(rr-r)==abs(cc-c) and rr!=r:
     dr=(rr-r)//abs(rr-r); dc=(cc-c)//abs(cc-c)
     # extend line away from rest of cluster at each endpoint only where background
     for sr,sc,step in [(r,c,-1),(rr,cc,1)]:
      y,x=sr+step*dr,sc+step*dc
      while 0<=y<len(out) and 0<=x<len(out[0]) and grid[y][x]==9:
       out[y][x]=color; y+=step*dr; x+=step*dc
     break
